function bindResponseScope(){document.querySelectorAll('[data-response-scope]').forEach(select=>select.onchange=async()=>{state.responseScope=["real","test","all"].includes(select.value)?select.value:"real";state.selected=null;if(state.mode==="builder")await previewBuilderDashboard();else await loadViewer(String(state.dashboard?.id||""))})}
function indicatorResponses(){return state.responses}
