function questionChoiceLabels(q){
  const out=new Map(),def=state.definition||{},qc=String(codeOf(q?.Question_Code)||"");
  for(const c of def.choices||[]){
    if(String(resolveRefCode(c.Question_Code,def.questions||[],"Question_Code"))!==qc)continue;
    const k=String(codeOf(c.Choix_Code)||"");
    if(k)out.set(k,String(first(c,["Libelle","Libellé","Valeur","Choix_Code"],k)));
  }
  const rc=resolveRefCode(q?.Referentiel_Code,def.referentials||[],"Referentiel_Code");
  if(rc){
    const ref=(def.referentials||[]).find(r=>String(codeOf(r.Referentiel_Code))===String(rc));
    const source=String(ref?.Type_source||"VALEURS_REFERENTIELS").trim().toUpperCase();
    if(source==="STRUCTURES"){
      for(const r of def.structures||[]){const k=String(codeOf(r.Structure_Code)||"");if(k)out.set(k,String(first(r,["Nom","Libelle","Libellé","Structure_Code"],k)));}
    }else{
      for(const r of def.referentialValues||[]){
        if(String(resolveRefCode(r.Referentiel_Code,def.referentials||[],"Referentiel_Code"))!==String(rc))continue;
        const k=String(codeOf(r.ValeurRef_Code)||"");
        if(k)out.set(k,String(first(r,["Libelle","Libellé","Valeur","ValeurRef_Code"],k)));
      }
    }
  }
  return out;
}
function dashboardNativeLabelOrder(q){return [...questionChoiceLabels(q).values()].map(v=>String(v))}
function dashboardSortRows(rows,mode="auto",nativeOrder=[]){const list=[...(rows||[])],m=String(mode||"auto");if(m==="auto"&&nativeOrder?.length){const pos=new Map(nativeOrder.map((v,i)=>[String(v),i]));return list.sort((a,b)=>{const ai=pos.has(String(a.label))?pos.get(String(a.label)):Number.MAX_SAFE_INTEGER,bi=pos.has(String(b.label))?pos.get(String(b.label)):Number.MAX_SAFE_INTEGER;return ai-bi})}if(m==="reverse")return list.reverse();if(m==="alpha_asc")return list.sort((a,b)=>String(a.label).localeCompare(String(b.label),"fr",{numeric:true}));if(m==="alpha_desc")return list.sort((a,b)=>String(b.label).localeCompare(String(a.label),"fr",{numeric:true}));if(m==="frequency_desc")return list.sort((a,b)=>Number(b.__freq??b.n??b.count??0)-Number(a.__freq??a.n??a.count??0));if(m==="frequency_asc")return list.sort((a,b)=>Number(a.__freq??a.n??a.count??0)-Number(b.__freq??b.n??b.count??0));if(m==="value_asc")return list.sort((a,b)=>String(a.label).localeCompare(String(b.label),"fr",{numeric:true}));if(m==="value_desc")return list.sort((a,b)=>String(b.label).localeCompare(String(a.label),"fr",{numeric:true}));return list}
function dashboardVentNativeOrder(vent){if(vent?.kind==="grouping")return (vent.grouping?.groups||[]).map(g=>String(g?.label||"").trim()).filter(Boolean);return dashboardNativeLabelOrder(vent?.q)}
function dashboardSeedVentilationGroups(vent,groups,factory){for(const label of dashboardVentNativeOrder(vent)){const l=String(label||"").trim();if(l&&!groups.has(l))groups.set(l,factory())}}
function indicatorQuestionType(q){return String(first(q,["Type_question","Type_reponse","Type","Format"],"")).toLowerCase()}
function indicatorNumeric(q){return /nombre|montant|num|decimal|décimal|entier|float|currency/.test(indicatorQuestionType(q))}
function indicatorMatrix(q){return indicatorQuestionType(q).includes("matrice")}
