function indicatorMatrixText(q){const t=indicatorQuestionType(q);return t.includes("matrice")&&t.includes("texte")}
function indicatorMatrixCategorical(q){const t=indicatorQuestionType(q);return t.includes("matrice")&&(t.includes("radio")||t.includes("checkbox")||t.includes("case"))}
function indicatorMulti(q){const t=indicatorQuestionType(q);return t.includes("case")||t.includes("checkbox")||((t.includes("liste")||t.includes("déroul")||t.includes("deroul"))&&isTrue(q?.Selection_multiple))||t.includes("matrice_checkbox")}
function indicatorDate(q){return indicatorQuestionType(q).includes("date")}
function indicatorBoolean(q){const t=indicatorQuestionType(q);return t.includes("bool")||t.includes("oui/non")}
function indicatorHasChoices(q){return questionChoiceLabels(q).size>0||indicatorBoolean(q)}
function indicatorTextual(q){return !indicatorNumeric(q)&&!indicatorMatrix(q)&&!indicatorDate(q)&&!indicatorHasChoices(q)}
function indicatorChoiceLabels(q){const out=questionChoiceLabels(q);if(!out.size&&indicatorBoolean(q)){out.set("true","Oui");out.set("false","Non");out.set("1","Oui");out.set("0","Non")}return out}
function dashboardItemKey(item){const rid=codeOf(item?.h?.response?.Reponse_Code)||String(item?.h?.response?.id||"");const fid=item?.f?(item.f.elementCode||item.f.elementId||""):"principal";return `${rid}::${fid}`}
function matrixRowsForQuestion(q){const all=state.definition?.questions||[],raw=String(q?.id??""),qc=String(codeOf(q?.Question_Code)||"");return all.filter(r=>isTrue(r.Est_ligne_matrice)&&(()=>{const p=codeOf(r.Question_parente_Code);return String(p)===raw||String(p)===qc})()).sort((a,b)=>Number(a.Ordre||a.manualSort||0)-Number(b.Ordre||b.manualSort||0))}
function matrixColumnsForQuestion(q){const all=state.definition?.matrixColumns||[],raw=String(q?.id??""),qc=String(codeOf(q?.Question_Code)||"");return all.filter(c=>{const p=codeOf(c.Question_Code);return String(p)===raw||String(p)===qc}).sort((a,b)=>Number(a.Ordre||a.manualSort||0)-Number(b.Ordre||b.manualSort||0))}
function matrixRowLabel(r){return String(first(r,["Libelle","Libellé","Titre","Question"],codeOf(r.Question_Code)))}
