function indicatorIsDescendantFicheType(childCode,parentCode){let cur=String(childCode||"");const target=String(parentCode||"");const seen=new Set;while(cur&&!seen.has(cur)){if(cur===target)return true;seen.add(cur);cur=indicatorFicheParentTypeCode(cur)}return false}
function indicatorFicheGroupSpec(raw,targetTypeCode){const v=String(raw||"");if(!v)return null;if(v.startsWith("q:"))return{kind:"main",questionCode:v.slice(2)};if(v.startsWith("fq:")){const rest=v.slice(3),i=rest.indexOf(":");if(i<0)return null;const typeCode=rest.slice(0,i),questionCode=rest.slice(i+1);if(typeCode!==String(targetTypeCode)&&!indicatorIsDescendantFicheType(typeCode,targetTypeCode))return null;return{kind:typeCode===String(targetTypeCode)?"same":"desc",typeCode,questionCode}}return{kind:"main",questionCode:v}}
