function indicatorCompositeBlock(q,id,hydrated){const group=indicatorConfig(q).__composites?.[id];if(!group||!Array.isArray(group.members))return "";const rows=[];let grand=0,any=false;for(const token of group.members){const isFiche=token.startsWith("fq:"),parts=token.split(":"),fc=isFiche?parts[1]:"",qc=isFiche?parts[2]:parts[1],questions=state.definition?.questions||[],src=questions.find(x=>String(codeOf(x.Question_Code))===String(qc));if(!src)continue;const ft=isFiche?indicatorFicheType(fc):null;let total=0,count=0;for(const h of hydrated){const values=isFiche?(h.fiches?.[fc]||[]).map(f=>f.answers?.[qc]):[h.principalAnswers?.[qc]];for(const value of values){if(value===null||value===undefined||String(value).trim()==="")continue;const n=Number(String(value).replace(/\s/g,"").replace(",","."));if(Number.isFinite(n)){total+=n;count++}}}if(count){grand+=total;any=true}const labelText=(ft?`${first(ft,["Libelle_singulier","Libellé_singulier","Libelle","Nom"],fc)} — `:"")+first(src,["Libelle","Libellé","Titre"],qc);rows.push(`<tr><td style="padding:7px;border-bottom:1px solid #e5e7eb">${escapeHtml(labelText)}</td><td style="padding:7px;text-align:right;border-bottom:1px solid #e5e7eb">${count?escapeHtml(total.toLocaleString("fr-FR",{maximumFractionDigits:2})):"—"}</td></tr>`)}const sum=group.sum?`<tr><th style="padding:9px;text-align:left">Total</th><th style="padding:9px;text-align:right">${any?escapeHtml(grand.toLocaleString("fr-FR",{maximumFractionDigits:2})):"—"}</th></tr>`:"";return `<div class="indicator-card"><h4>${escapeHtml(group.title||"Indicateur regroupé")}</h4><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left">Montant / variable</th><th style="text-align:right">Somme</th></tr></thead><tbody>${rows.join("")}${sum}</tbody></table></div>`}
function renderIndicators(q){const tokens=indicatorQuestionCodes(q),hydrated=indicatorHydratedResponses(),title=first(q,["Libelle","Libellé","Titre"],"Indicateurs"),blocks=[];if(!indicatorHasCampaign())return `<section class="content-indicators" id="indicator-${escapeHtml(codeOf(q.Question_Code))}" data-display-block="${escapeHtml(codeOf(q.Question_Code))}"><h3 style="${escapeHtml(labelStyle(q))}">📊 ${escapeHtml(title)}</h3><div class="help">Aucune campagne n’est identifiable dans cet aperçu. Les indicateurs ne mélangent pas automatiquement les données de plusieurs campagnes. Ouvrez un lien de campagne pour afficher ses résultats.</div></section>`;for(const raw of tokens){if(raw.startsWith("g:")){const html=indicatorCompositeBlock(q,raw.slice(2),hydrated);if(html)blocks.push(html);continue}let kind="q",typeCode="",qc=raw;if(raw.startsWith("f:")){kind="f";typeCode=raw.slice(2)}else if(raw.startsWith("fq:")){kind="fq";const rest=raw.slice(3),i=rest.indexOf(":");if(i<0)continue;typeCode=rest.slice(0,i);qc=rest.slice(i+1)}else if(raw.startsWith("q:"))qc=raw.slice(2);const cfg=indicatorSourceConfig(q,raw,kind);if(kind==="f"){const ft=indicatorFicheType(typeCode);if(!ft)continue;const counts=hydrated.map(h=>(h.fiches?.[typeCode]||[]).length),total=counts.reduce((a,b)=>a+b,0),withAny=counts.filter(n=>n>0).length,parts=[];if(cfg.stats.has("total"))parts.push([resolveRefCode(ft.Parent_Code,state.definition?.ficheTypes||[],"TypeFiche_Code")?"Nombre total de sous-fiches":"Nombre total de fiches",total]);if(cfg.stats.has("withAny"))parts.push(["Répondants avec au moins une fiche",withAny]);if(counts.length&&cfg.stats.has("mean"))parts.push(["Nombre moyen de fiches par répondant",total/counts.length]);if(counts.length&&cfg.stats.has("min"))parts.push(["Nombre minimum de fiches par répondant",Math.min(...counts)]);if(counts.length&&cfg.stats.has("max"))parts.push(["Nombre maximum de fiches par répondant",Math.max(...counts)]);const ficheTitle=first(ft,["Libelle_pluriel","Libellé_pluriel","Libelle_singulier","Libellé_singulier","Libelle","Nom"],typeCode);if(cfg.groupBy){const spec=indicatorFicheGroupSpec(cfg.groupBy,typeCode),groupSrc=spec?.kind==="main"?(state.definition?.questions||[]).find(x=>String(codeOf(x.Question_Code))===String(spec.questionCode)&&!resolveRefCode(x.TypeFiche_Code,state.definition?.ficheTypes||[],"TypeFiche_Code")):spec?indicatorFicheQuestion(spec.questionCode,spec.typeCode):null;if(groupSrc){const pairs=hydrated.flatMap(h=>indicatorFicheCountGroupData(h,typeCode,spec));blocks.push(indicatorFicheCountCrossBlock(ft,groupSrc,pairs,cfg.stats,ficheTitle));continue}}blocks.push(`<div class="indicator-card"><h4>${escapeHtml(ficheTitle)}</h4>${indicatorKpis(parts)}</div>`);continue}let src,vals,pairs=[];if(kind==="fq"){src=indicatorFicheQuestion(qc,typeCode);if(!src)continue;const rows=hydrated.flatMap(h=>(h.fiches?.[typeCode]||[]));vals=rows.map(f=>f.answers?.[qc]).filter(v=>v!==undefined&&v!==null&&v!==""&&!(Array.isArray(v)&&!v.length));if(cfg.groupBy)pairs=rows.map(f=>[f.answers?.[cfg.groupBy],f.answers?.[qc]])}else{src=(state.definition?.questions||[]).find(x=>String(codeOf(x.Question_Code))===String(qc)&&!resolveRefCode(x.TypeFiche_Code,state.definition?.ficheTypes||[],"TypeFiche_Code"));if(!src)continue;vals=hydrated.map(h=>h.principalAnswers?.[qc]).filter(v=>v!==undefined&&v!==null&&v!==""&&!(Array.isArray(v)&&!v.length));if(cfg.groupBy)pairs=hydrated.map(h=>[h.principalAnswers?.[cfg.groupBy],h.principalAnswers?.[qc]])}const ft=kind==="fq"?indicatorFicheType(typeCode):null,labelText=`${kind==="fq"&&ft?`${first(ft,["Libelle_singulier","Libellé_singulier","Libelle","Nom"],typeCode)} — `:""}${first(src,["Libelle","Libellé","Titre"],qc)}`;if(cfg.groupBy){const groupSrc=kind==="fq"?indicatorFicheQuestion(cfg.groupBy,typeCode):(state.definition?.questions||[]).find(x=>String(codeOf(x.Question_Code))===String(cfg.groupBy)&&!resolveRefCode(x.TypeFiche_Code,state.definition?.ficheTypes||[],"TypeFiche_Code"));if(groupSrc){blocks.push(indicatorCrossBlock(src,groupSrc,pairs,cfg.stats,cfg.chart,labelText));continue}}blocks.push(indicatorNumeric(src)?indicatorNumericBlock(vals,cfg.stats,labelText):indicatorCategoricalBlock(src,vals,cfg.stats,cfg.chart,labelText))}return `<section class="content-indicators" id="indicator-${escapeHtml(codeOf(q.Question_Code))}" data-display-block="${escapeHtml(codeOf(q.Question_Code))}"><h3 style="${escapeHtml(labelStyle(q))}">📊 ${escapeHtml(title)}</h3><div style="display:grid;gap:14px">${blocks.join("")||'<div class="help">Aucune donnée disponible pour les indicateurs sélectionnés dans cette campagne.</div>'}</div></section>`}

function configuredIndicatorBlocks(){return (state.definition?.questions||[]).filter(q=>String(first(q,["Type_question","Type_reponse","Type","Format"],"")).trim().toLowerCase()==="indicateurs"&&active(q))}
function responseLabel(h,i){const r=h.response||{};const c=state.campaigns.find(x=>sameRef(r.Campagne_Code,x,"Campagne_Code"));return String(c?.Valeur_personnalisation_Libelle||c?.Valeur_personnalisation||r.Nom_repondant||r.Repondant||`Réponse ${i+1}`)}
function scalarDisplay(v,q){if(Array.isArray(v))return v.map(x=>indicatorGroupLabel(q,x)).join(", ");if(v==null||v==="")return"—";return indicatorNumeric(q)?String(v):indicatorGroupLabel(q,v)}
function selectedTokens(){const out=[];for(const b of configuredIndicatorBlocks())for(const t of indicatorQuestionCodes(b))if(!out.includes(t))out.push(t);return out}
function tokenTitle(t){if(t.startsWith("f:")){const f=indicatorFicheType(t.slice(2));return f?`Nb ${ficheLabel(f)}`:t}if(t.startsWith("fq:")){const r=t.slice(3),i=r.indexOf(":"),fc=r.slice(0,i),qc=r.slice(i+1),q=indicatorFicheQuestion(qc,fc);return q?questionLabel(q):t}const qc=t.startsWith("q:")?t.slice(2):t,q=(state.definition?.questions||[]).find(x=>codeOf(x.Question_Code)===qc);return q?questionLabel(q):t}
function responseTokenValue(h,t){if(t.startsWith("f:"))return (h.fiches?.[t.slice(2)]||[]).length;if(t.startsWith("fq:")){const r=t.slice(3),i=r.indexOf(":"),fc=r.slice(0,i),qc=r.slice(i+1),q=indicatorFicheQuestion(qc,fc),vals=(h.fiches?.[fc]||[]).map(x=>x.answers?.[qc]).filter(v=>v!==undefined&&v!==null&&v!=="");if(!vals.length)return"—";if(q&&indicatorNumeric(q))return vals.map(Number).filter(Number.isFinite).reduce((a,b)=>a+b,0);return [...new Set(vals.flatMap(v=>Array.isArray(v)?v:[v]).map(v=>indicatorGroupLabel(q,v)))].join(", ")}const qc=t.startsWith("q:")?t.slice(2):t,q=(state.definition?.questions||[]).find(x=>codeOf(x.Question_Code)===qc);return scalarDisplay(h.principalAnswers?.[qc],q)}
function renderHeader(){const d=state.dashboard,c=state.campaigns[0],sharedView=state.mode==="view";return `<div class="dash-head"><div><h1>${escapeHtml(d?.Nom||"Tableau de bord")}</h1><div class="muted">${escapeHtml(c?.Nom||"Campagne")} · ${state.responses.length} réponse(s)${sharedView?"":` · ${escapeHtml(responseScopeLabel())}`}</div></div><div class="dashboard-view-actions">${sharedView?"":responseScopeControl()}${dashboardPeriodControl()}<button type="button" data-print-current>Imprimer / PDF cet onglet</button><button type="button" data-print-all>Imprimer / PDF tout le Dashboard</button><button type="button" data-export-dashboard>Exporter les données</button></div></div>`}
function renderGlobal(){const blocks=configuredIndicatorBlocks();return `<div class="dash-kpis"><div class="dash-kpi"><span>Réponses</span><strong>${state.responses.length}</strong></div><div class="dash-kpi"><span>Blocs d’indicateurs</span><strong>${blocks.length}</strong></div></div><div class="dash-grid" style="margin-top:14px">${blocks.map(renderIndicators).join("")||'<div class="dash-card">Aucun bloc Indicateurs n’est configuré dans cette version.</div>'}</div>`}
// Pour les questionnaires permanents, distinguer activité de saisie et validation globale.
function periodActivityLabel(h){
 if(!state.periodCode)return String(h.response?.Statut||"—");
 const answers=h.principalAnswers||{};
 const hasPrincipal=Object.values(answers).some(v=>v!==null&&v!==undefined&&String(v).trim()!=="");
 const hasFiches=Object.values(h.fiches||{}).some(rows=>Array.isArray(rows)&&rows.some(f=>String(f.periodeCode||"")===state.periodCode));
 return hasPrincipal||hasFiches?"Saisie enregistrée":"Aucune saisie";
}
function renderParticipants(){const tokens=selectedTokens();return `<div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Répondant</th><th>Statut</th>${tokens.map(t=>`<th>${escapeHtml(tokenTitle(t))}</th>`).join("")}</tr></thead><tbody>${state.hydrated.map((h,i)=>`<tr data-response="${i}"><td><strong>${escapeHtml(responseLabel(h,i))}</strong></td><td>${escapeHtml(periodActivityLabel(h))}</td>${tokens.map(t=>`<td>${escapeHtml(String(responseTokenValue(h,t)))}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function renderDetail(i){const h=state.hydrated[i];if(!h)return"";const main=(state.definition?.questions||[]).filter(q=>active(q)&&!resolveRefCode(q.TypeFiche_Code,state.definition?.ficheTypes||[],"TypeFiche_Code")&&!['description','sommaire','indicateurs','tableau_donnees'].includes(String(first(q,["Type_question","Type"],"")).toLowerCase()));const ficheCards=(state.definition?.ficheTypes||[]).map(ft=>{const fc=codeOf(ft.TypeFiche_Code),rows=h.fiches?.[fc]||[];if(!rows.length)return"";return `<div class="dash-card"><h3>${escapeHtml(ficheLabel(ft))} (${rows.length})</h3>${rows.map((r,n)=>`<div style="margin:10px 0;padding-top:8px;border-top:1px solid #eee"><strong>#${n+1}</strong>${(state.definition.questions||[]).filter(q=>resolveRefCode(q.TypeFiche_Code,state.definition.ficheTypes,"TypeFiche_Code")===fc).map(q=>`<div class="answer-row"><strong>${escapeHtml(questionLabel(q))}</strong>${escapeHtml(scalarDisplay(r.answers?.[codeOf(q.Question_Code)],q))}</div>`).join("")}</div>`).join("")}</div>`}).join("");return `<button class="back-btn" data-back>← Retour aux répondants</button><h2>${escapeHtml(responseLabel(h,i))}</h2><div class="participant-detail-grid"><div class="dash-card"><h3>Réponse principale</h3>${main.map(q=>`<div class="answer-row"><strong>${escapeHtml(questionLabel(q))}</strong>${escapeHtml(scalarDisplay(h.principalAnswers?.[codeOf(q.Question_Code)],q))}</div>`).join("")}</div>${ficheCards}</div>`}
function csvCell(v){const s=String(v??"").replace(/\r?\n/g," ");return /[;"\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s}
function dashboardExportRows(){const rows=[["Dashboard",state.dashboard?.Nom||"Tableau de bord"],["Campagne",state.campaigns?.[0]?.Nom||""],["Réponses",state.responses.length],["Périmètre",responseScopeLabel()],["Période",state.periodCode?(state.periods.find(p=>codeOf(p.Periode_Code)===state.periodCode)?.Libelle||state.periodCode):"Vue globale (sans filtre)"],[]],root=document.querySelector('#root');const panels=[...root.querySelectorAll('[data-view-tab-panel]')],targets=panels.length?panels:[root];targets.forEach((panel,pi)=>{const tabId=panel.dataset?.viewTabPanel||"",btn=tabId?root.querySelector(`[data-view-tab="${CSS.escape(tabId)}"]`):null;rows.push([btn?.textContent?.trim()||`Vue ${pi+1}`]);panel.querySelectorAll('.dash-kpi').forEach(k=>rows.push([k.querySelector('span')?.textContent?.trim()||"Indicateur",k.querySelector('strong')?.textContent?.trim()||""]));panel.querySelectorAll('.indicator-card,.dash-card,.dashboard-configured-block').forEach(card=>{const title=card.querySelector('h3,h4')?.textContent?.trim();if(title)rows.push([title]);card.querySelectorAll('table').forEach(table=>{[...table.rows].forEach(tr=>rows.push([...tr.cells].map(td=>td.textContent.trim())));rows.push([])});card.querySelectorAll('.metric-table>div').forEach(line=>rows.push([...line.children].map(x=>x.textContent.trim())));rows.push([])});rows.push([])});return rows}
