function renderBlockList(blocks,group,cfg={}){const qByCode=new Map(builderIndicatorBlocks(group).map(q=>[String(codeOf(q.Question_Code)),q]));return (blocks||[]).slice().sort((a,b)=>(a.order||0)-(b.order||0)).map(b=>{if(b.type==='respondents')return `<div class="dash-kpi"><span>${escapeHtml(b.title||'Répondants')}</span><strong>${state.responses.length}</strong></div>`;if(b.type==='text')return `<div class="dash-card">${b.title?`<h3>${escapeHtml(b.title)}</h3>`:""}<div class="dashboard-text">${escapeHtml(b.text||"").replace(/\n/g,'<br>')}</div></div>`;if(b.type==='reuse'){const q=qByCode.get(String(b.indicatorCode||""));return q?`<div class="dashboard-configured-block">${b.title?`<h3>${escapeHtml(b.title)}</h3>`:""}${applyReuseDisplay(renderIndicators(q),b.display)}</div>`:""}if(b.type==='indicator')return renderCustomIndicatorBlock(b,group,cfg);return""}).join("")}
function renderBlocksFromConfig(cfg,group){const tabs=normalizeDashboardTabs(cfg);if(tabs.length===1)return `<div class="dashboard-tabs"><div class="dashboard-tab-panel is-active" data-view-tab-panel="${escapeHtml(tabs[0].id)}"><div class="dash-grid">${renderBlockList(tabs[0].blocks,group,cfg)||'<div class="dash-card">Aucun bloc configuré.</div>'}</div></div></div>`;return `<div class="dashboard-tabs"><div class="dashboard-tab-nav">${tabs.map((t,i)=>`<button type="button" class="dashboard-tab-button ${i===0?'is-active':''}" data-view-tab="${escapeHtml(t.id)}">${escapeHtml(t.title||`Onglet ${i+1}`)}</button>`).join("")}</div>${tabs.map((t,i)=>`<div class="dashboard-tab-panel ${i===0?'is-active':''}" data-view-tab-panel="${escapeHtml(t.id)}" ${i===0?'':'hidden'}><div class="dash-grid">${renderBlockList(t.blocks,group,cfg)||'<div class="dash-card">Aucun bloc configuré.</div>'}</div></div>`).join("")}</div>`}
function bindDashboardViewTabs(root=document){root.querySelectorAll('[data-view-tab]').forEach(btn=>btn.onclick=()=>{const host=btn.closest('.dashboard-tabs');host.querySelectorAll('[data-view-tab]').forEach(x=>x.classList.toggle('is-active',x===btn));host.querySelectorAll('[data-view-tab-panel]').forEach(p=>{const active=p.dataset.viewTabPanel===btn.dataset.viewTab;p.hidden=!active;p.classList.toggle('is-active',active)})})}
async function previewBuilderDashboard(){const groupCode=document.querySelector('#builder-campaign')?.value||"";if(!groupCode)throw new Error('Sélectionnez une campagne.');const group=prepareCampaignData(groupCode),cfg=builderConfigFromForm(),host=document.querySelector('#builder-preview');host.hidden=false;host.innerHTML=`<div class="preview-head"><div><strong>Aperçu du tableau de bord</strong><div class="muted">${escapeHtml(responseScopeLabel())}</div>${responseScopeControl()}</div><button type="button" id="close-preview">Fermer l’aperçu</button></div>${renderBlocksFromConfig(cfg,group)}`;bindDashboardViewTabs(host);bindResponseScope();document.querySelector('#close-preview').onclick=()=>host.hidden=true;host.scrollIntoView({behavior:'smooth',block:'start'})}
async function saveBuilderDashboard(){const sel=document.querySelector('#builder-dashboard'),name=String(document.querySelector('#builder-name').value||"").trim(),group=String(document.querySelector('#builder-campaign').value||"").trim();if(!name){alert('Saisissez un nom de Dashboard.');return}if(!group){alert('Sélectionnez une campagne.');return}const cfg=builderConfigFromForm(),existing=sel.value!=="new"?builderRow(sel.value):null;let token=String(existing?.Jeton_acces||existing?.Jeton_dashboard||"").trim()||`Dashboard_${uid('ACCES').replace(/^ACCES_/,"")}`,url=shareUrlForToken(token)||String(existing?.URL_dashboard||"").trim();if(existing){const values={Nom:name,Campagne_Code:group,Jeton_acces:token,URL_dashboard:url,Configuration_JSON:JSON.stringify(cfg),Actif:true};await grist.docApi.applyUserActions([["UpdateRecord","DASHBOARDS",existing.id,values]])}else{const values={Dashboard_Code:uid('DASH'),Nom:name,Campagne_Code:group,Jeton_acces:token,URL_dashboard:url,Configuration_JSON:JSON.stringify(cfg),Actif:true,Date_creation:Date.now()/1000};await grist.docApi.applyUserActions([["AddRecord","DASHBOARDS",null,values]])}await reloadDashboardRows();renderBuilder();const match=(state.loaded.DASHBOARDS||[]).filter(r=>r.Nom===name&&String(r.Campagne_Code||"")===group).sort((a,b)=>Number(b.id)-Number(a.id))[0];if(match){rememberLastDashboard(match);document.querySelector('#builder-dashboard').value=String(match.id);document.querySelector('#builder-dashboard').dispatchEvent(new Event('change'))}document.querySelector('#status').innerHTML='<div class="status-info">Dashboard enregistré.</div>';setTimeout(()=>document.querySelector('#status').innerHTML='',1800)}
function configuredDashboardBlocks(){const cfg=dashboardConfig(state.dashboard);return normalizeDashboardTabs(cfg).flatMap(t=>t.blocks||[])}
function renderDashboardGlobal(){const cfg=dashboardConfig(state.dashboard),custom=configuredDashboardBlocks();if(!custom.length)return originalRenderGlobal();const group=dashboardGroupRows(state.loaded?.CAMPAGNES||[]).find(g=>g.code===String(state.dashboard?.Campagne_Code||""))||{code:String(state.dashboard?.Campagne_Code||""),rows:state.campaigns,first:state.campaigns[0]};return `<div class="dash-grid" style="margin-top:14px">${renderBlocksFromConfig(cfg,group)||'<div class="dash-card">Aucun bloc configuré.</div>'}</div>`}
const originalRenderGlobal=renderGlobal;
renderGlobal=renderDashboardGlobal;
async function load(){loadAdminModuleNav();const token=param('Dashboard_'),consultation=String(param('mode')||"").toLowerCase()==="view";if(consultation||token)state.responseScope="real";document.body.classList.toggle('dashboard-view-mode',consultation);if(!consultation&&!token){state.mode='builder';const loaded={};for(const t of TABLES){if(t==='DASHBOARDS')loaded[t]=await fetchDashboardTable();else if(t==='BIBLIOTHEQUE_REGROUPEMENTS'||t==='PERIODES_QUESTIONNAIRE'||t==='QUESTIONNAIRES'||t==='PAGES'||t==='SECTIONS'){try{loaded[t]=await fetch(t)}catch{loaded[t]=[]}}else loaded[t]=await fetch(t)}state.loaded=loaded;await reloadDashboardRows();document.querySelector('#status').innerHTML='';renderBuilder();return}state.mode='view';await loadViewer("",token,false);state.loaded=state.loaded||null}

document.addEventListener('click',e=>{const btn=e.target.closest?.('[data-view-tab]');if(!btn)return;const host=btn.closest('.dashboard-tabs');if(!host)return;host.querySelectorAll('[data-view-tab]').forEach(x=>x.classList.toggle('is-active',x===btn));host.querySelectorAll('[data-view-tab-panel]').forEach(p=>{const active=p.dataset.viewTabPanel===btn.dataset.viewTab;p.hidden=!active;p.classList.toggle('is-active',active)})});
grist.ready({requiredAccess:'full'});load().catch(e=>{document.querySelector('#status').innerHTML=`<div class="status-error">${escapeHtml(e?.message||e)}</div>`});
